def fit_field(width, height, coast, samples):
    """Return the public field list sorted by (y, x), with one
    {x, y, dx, dy, error, gap} row for each sea cell. coast and samples
    retain their public shapes. Preserve inputs."""
    coast_set = set(tuple(c) for c in coast)
    by_cell = {}
    for s in samples:
        by_cell.setdefault((s["x"], s["y"]), []).append(s)

    field = []
    for y in range(height):
        for x in range(width):
            if (x, y) in coast_set:
                continue
            cell_samples = by_cell.get((x, y), [])
            if not cell_samples:
                field.append({"x": x, "y": y, "dx": 0, "dy": 0,
                              "error": 0, "gap": 0})
                continue
            best = None
            best_error = None
            errors = {}
            for dx in (-1, 0, 1):
                for dy in (-1, 0, 1):
                    err = sum(s["weight"] * (abs(dx - s["dx"]) + abs(dy - s["dy"]))
                              for s in cell_samples)
                    errors[(dx, dy)] = err
                    if best_error is None or err < best_error:
                        best = (dx, dy)
                        best_error = err
            # second distinct vector's lowest error
            distinct = [e for v, e in errors.items() if v != best]
            second = min(distinct) if distinct else best_error
            gap = second - best_error
            field.append({"x": x, "y": y, "dx": best[0], "dy": best[1],
                          "error": best_error, "gap": gap})
    return field

