class FieldFitTests(unittest.TestCase):
    def test_local_check_two_by_two(self):
        from engines.analysis.field_fit import fit_field
        coast = [[1, 0]]
        samples = [
            {"x": 0, "y": 0, "dx": -1, "dy": 0, "weight": 1},
            {"x": 0, "y": 0, "dx": 1, "dy": 0, "weight": 1},
        ]
        field = fit_field(2, 2, coast, samples)
        by_cell = {(r["x"], r["y"]): r for r in field}
        self.assertNotIn((1, 0), by_cell)
        r = by_cell[(0, 0)]
        self.assertEqual((r["dx"], r["dy"]), (-1, 0))
        self.assertEqual(r["error"], 2)
        self.assertEqual(r["gap"], 0)
        for cell in [(0, 1), (1, 1)]:
            r = by_cell[cell]
            self.assertEqual((r["dx"], r["dy"]), (0, 0))
            self.assertEqual(r["error"], 0)
            self.assertEqual(r["gap"], 0)

    def test_field_sorted_by_yx(self):
        from engines.analysis.field_fit import fit_field
        field = fit_field(2, 2, [], [])
        keys = [(r["y"], r["x"]) for r in field]
        self.assertEqual(keys, sorted(keys))


